【适用范围】
作为长效保护底漆涂装在中等至严重腐蚀环境中的钢材表面。本品可被多种专门的油漆配套涂覆，也可为喷砂清洁过的钢板表面提供临时保护，作为焊接底漆。同时也可用作防火涂料的配套高级防锈底漆。

