表面处理：涂装表面应先涂上适当的底漆，同时表面必须保持清洁、干爽并将杂质除去，混凝土、水泥表面必须完全干燥，PH＜10、含水率小于10%。特殊表面的处理方法请向本公司技术部查询。

【建议油漆配套】
